contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Call addReward to trigger the difference in transferOwnership
        c.addReward(address(0x1));

        // Now stake some tokens to have balance
        address staker = address(0x123);

        // We need to make staker have balance to trigger the updateReward modifier
        // First, transfer staking token to staker
        // The staking token is this contract itself (address(this) in constructor)
        // We need to approve and transfer
        vm.prank(staker);
        // Stake 100 tokens
        // But first we need to give staker tokens
        // Since staking token is address(this) (the test contract), we can mint directly
        // Actually, the staking token is an IERC20 at address(this)
        // Let's use vm.deal to give staker eth? No, we need ERC20 tokens.
        // The simplest: just call with a staker that has staking tokens
        // We'll deploy a mock ERC20? No, only C is allowed.
        // Let's use the fact that we can call stakeFor with staker's approval

        // Actually, we need to have stakingToken.balanceOf(msg.sender) > 0 for stakeAll
        // Let's just stake directly by having the test contract approve itself
        // This is a contrived scenario but works:
        vm.startPrank(staker);
        // We need to approve the staking token (which is address(this)) to spend from staker
        // Since address(this) is the test contract, we can make it approve...
        // This is getting complicated. Let's use a simpler approach:
        // We'll use the fact that transferOwnership is changed; we can just call 
        // a function that checks it directly.
        // Actually, the change is in transferOwnership itself, not addReward.
        // The test must show that after addReward, something diverges.
        // Let's look at the difference: P.transferOwnership() != M.transferOwnership()
        // That means calling transferOwnership with address(0) should succeed in M but revert in P.
        // So we can just call c.transferOwnership(address(0)) and see if it reverts.

        bool ok;
        try c.transferOwnership(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference P, it should revert (ok = false)
        // In buggy M, it should succeed (ok = true)
        // So we assert that ok is true for the test to pass on reference? No, we want reference to pass.
        // The property is: P.revert when transferring to address(0), M does not.
        // So for the test to PASS on reference, we assert that ok is false.
        // For the test to FAIL on buggy, M would make ok true and assertion fails.
        assertTrue(!ok, "transferOwnership to address(0) should revert in reference");
    }
}

