pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Use a non-owner account
        address attacker = address(0x1234);
        vm.prank(attacker);
        // Try to call addReward; in reference it reverts, in buggy it succeeds
        bool ok;
        try c.addReward(address(0x9999)) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: ok == false (reverts due to onlyOwner)
        // Bug: ok == true (onlyOwner modifier is empty)
        assertTrue(ok);
    }
}

