        // In reference: totalSupply() == 100, so _rewardPerToken calculates non-zero
        // In mutant: totalSupply() == 0, so _rewardPerToken returns stored value (0)
        bool refHasPositiveReward = c.rewardPerToken(address(0x1)) > 0;

